public class GrayPaintScale_getPaint_TriageGen1Test {





    @Test
    public void testGetPaint_MidPoint() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test value at midpoint (50.0)
        // (50-0)/(100-0) * 255 = 0.5 * 255 = 127.5 -> cast to int is 127
        Paint result = scale.getPaint(50.0);
        assertEquals(new Color(127, 127, 127), result);
    }






}

