public class GrayPaintScale_getPaint_TriageGen1Test {







    @Test
    public void testGetPaint_BelowLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Test value below lower bound (should be clamped to lower bound)
        // Math.max(5.0, 10.0) -> 10.0 -> Color(0,0,0)
        Paint result = scale.getPaint(5.0);
        assertEquals(new Color(0, 0, 0), result);
    }




}

